// Nao meche aqui embaixo plmds, aqui é o código que monta as categoria, entao deixa isso dai quieto pfvr
// deixa que se precisar mexer em alguma coisa, me chama (adryan)


function criarCardFilme(filme) {
  const card = document.createElement("div");
  card.className = "card-filme";

  const capa = document.createElement("div");
  capa.className = "capa-filme";

    //se tiver um link de imagem preenchido, usa ele de fundo, ajuda de ia isso ai
  if (filme.imagem) {
    capa.style.backgroundImage = `url('${filme.imagem}')`;
    capa.style.backgroundSize = "cover";
    capa.style.backgroundPosition = "center";
  }

  const nome = document.createElement("p");
  nome.className = "nome-filme";
  nome.textContent = filme.nome;

  const nota = document.createElement("p");
  nota.className = "nota-filme";
  nota.textContent = `⭐ ${filme.nota}`;

  card.appendChild(capa);
  card.appendChild(nome);
  card.appendChild(nota);

  return card;
}

function criarFileiraCategoria(nomeCategoria, listaDeFilmes) {
  const secao = document.createElement("section");
  secao.className = "categoria";

  const titulo = document.createElement("h2");
  titulo.className = "titulo-categoria";
  titulo.textContent = nomeCategoria;

  const lista = document.createElement("div");
  lista.className = "lista-filmes";

  listaDeFilmes.forEach((filme) => {
    lista.appendChild(criarCardFilme(filme));
  });

  secao.appendChild(titulo);
  secao.appendChild(lista);

  return secao;
}

function montarCatalogo() {
  const container = document.getElementById("categorias");

  for (const nomeCategoria in filmesPorCategoria) {
    const listaDeFilmes = filmesPorCategoria[nomeCategoria];
    const fileira = criarFileiraCategoria(nomeCategoria, listaDeFilmes);
    container.appendChild(fileira);
  }
}

// é o bagui que faz espera a página carrega toda antes de roda
document.addEventListener("DOMContentLoaded", montarCatalogo);